#!/usr/bin/env python3

import subprocess
import sys
import os

# Add the tmp directory to Python path to import user_config
sys.path.append('/tmp')

try:
    from user_config import get_usernames, get_passwords, get_sudo_config
except ImportError as e:
    print(f"Error importing user_config: {e}")
    sys.exit(1)

def run_command(command):
    """Run a shell command and return the result"""
    try:
        result = subprocess.run(command, shell=True, check=True, 
                              stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        return result.stdout.strip()
    except subprocess.CalledProcessError as e:
        print(f"Error running command '{command}': {e.stderr}")
        return None

def main():
    # Get the configuration data
    usernames = get_usernames()
    passwords = get_passwords()
    sudo_config = get_sudo_config()

    print("Setting up users...")

    # Create users and set passwords
    for username in usernames:
        # Create the user
        print(f"Creating user: {username}")
        result = run_command(f"useradd -m {username}")
        if result is None:
            print(f"Failed to create user {username}")
            continue

        # Set the password
        if username in passwords:
            print(f"Setting password for user: {username}")
            password = passwords[username]
            try:
                # Using echo and chpasswd to set the password
                process = subprocess.Popen(['chpasswd'], stdin=subprocess.PIPE, 
                                         stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
                output, error = process.communicate(input=f"{username}:{password}")
                if process.returncode != 0:
                    print(f"Error setting password for {username}: {error}")
                else:
                    print(f"Password set for {username}")
            except Exception as e:
                print(f"Exception setting password for {username}: {e}")

    # Add sudo configuration
    print("Adding sudo configuration...")
    try:
        with open('/etc/sudoers', 'a') as sudoers_file:
            sudoers_file.write(f"\n{sudo_config}\n")
        print("Sudo configuration added")
    except PermissionError:
        print("Permission denied: Cannot write to /etc/sudoers")
        print("Try running with sudo privileges")
    except Exception as e:
        print(f"Error writing to /etc/sudoers: {e}")

if __name__ == "__main__":
    main()
